fn solve(n: i8) -> bool {
    debug_assert!((1..=99).contains(&n));

    if n < 12 {
        // false for 1, 7, 9, 10, 11; true otherwise (2..=8 excluding 7 and 9)
        return !matches!(n, 1 | 7 | 9 | 10 | 11);
    }

    if n > 12 && n < 30 {
        return false;
    }

    if n > 69 && n < 80 {
        return false;
    }

    if n > 89 {
        return false;
    }

    // Remaining values: 12, 30..=69, 80..=89
    // true iff last digit is not 1, 7, or 9
    let last_digit = (n % 10) as i8;
    !matches!(last_digit, 1 | 7 | 9)
}